type CopySurface = Parameters<EngineInterface['ui']['copy']>[0]['surface']

const STORE_KEY_RECENT_FOLDERS = 'recentFolders'
const STORE_KEY_IS_SEEDED = 'isSeededFromDesktopSessions'
const STORE_KEY_USAGE_ENDPOINT = 'usageEndpoint'
// The plan usage endpoint the engine's /usage reads (five_hour, seven_day and
// the model-scoped weekly windows in limits[]); the bearer header is the engine's.
const USAGE_ENDPOINT_INTERVAL_MS = 60_000
const SESSION_USAGE_INTERVAL_MS = 5_000
// The value in the folder list that opens the folder picker.
const BROWSE_OPTION = '<browse for a folder>'
// The engine refuses a Select with more than 64 options (and with it the whole
// band), so the list draws at most that many; the store still keeps 100.
const SELECT_OPTION_LIMIT = 64
// Newest records first; enough to cover months of sessions without reading
// every record the desktop app has ever kept.
const SESSION_RECORD_READ_LIMIT = 1500
const FOLDER_PICKER_TIMEOUT_MS = 10 * 60 * 1000
const NO_FOLDER_CHOSEN = '<no folder chosen>'
// Columns the folder labels may take: what the band leaves beside the Browse
// and Copy buttons, kept between a readable minimum and a tidy maximum.
const COLUMNS_BESIDE_FOLDER_LABEL = 40
const MINIMUM_FOLDER_LABEL_WIDTH = 24
const MAXIMUM_FOLDER_LABEL_WIDTH = 72

const recentFoldersState = { plugin: 'conversation-toolbar', key: 'recentFolders' } as const
const usageAtom = atom({ plugin: 'conversation-toolbar', key: 'usage' } as const, null as UsageSnapshot | null)
// Whether the usage detail row stays open (toggled by the token-count button).
const usageDetailsPinnedAtom = atom({ plugin: 'conversation-toolbar', key: 'usageDetailsPinned' } as const, false)
// The folder a move is waiting to reach, and the dots of its note.
const pendingMoveAtom = atom({ plugin: 'conversation-toolbar', key: 'pendingMove' } as const, null as string | null)
const movingDotsAtom = atom({ plugin: 'conversation-toolbar', key: 'movingDots' } as const, 1)
const MOVING_DOTS_MAXIMUM = 6
const MOVING_DOTS_INTERVAL_MS = 400
// This session's subagents for the dots, refreshed from `$.agent.list()`.
const subagentsAtom = atom({ plugin: 'conversation-toolbar', key: 'subagents' } as const, [] as SubagentRecord[])
const SUBAGENT_LIST_INTERVAL_MS = 2_000
// The desktop app's session view server and its pane tool.
const TASKS_PANE_SERVER = 'ccd_view'
const TASKS_PANE_TOOL = 'show_pane'
// The button beside the dots that opens the pane: an arrow out to the pane
// (a math-axis glyph, so it sits on the dots' centre line; the trigram ☰ sat above it).
const OPEN_TASKS_GLYPH = '↗'
// Lines the dots' tooltip lists below the summary, newest first.
const SUBAGENT_TOOLTIP_LINE_LIMIT = 15
// The main conversation's Monitors for the waiting clocks.
const monitorsAtom = atom({ plugin: 'conversation-toolbar', key: 'monitors' } as const, [] as MonitorRecord[])
// How often the clocks' tooltip (waited, stops in) is redrawn while one waits.
// A waiting clock's countdown in minutes redraws this often; in its last
// minute, every poll.
const MONITOR_COUNTDOWN_REFRESH_MS = 10_000
// The Copy Transcript Path button says how the copy went for this long.
const copyFeedbackAtom = atom({ plugin: 'conversation-toolbar', key: 'copyFeedback' } as const, null as CopyFeedback | null)
const COPY_FEEDBACK_DURATION_MS = 2_000
const COPY_BUTTON_LABELS: Record<CopyFeedback | 'idle', string> = {
  idle: 'Copy Transcript Path',
  copied: 'Copied ✓',
  failed: 'Copy failed',
}

// Buttons other programs ask for through the button folder, and the frame
// their dots draw.
const NO_EXTERNAL_BUTTONS: ExternalButtonState = { buttons: [], frame: 0 }
const externalButtonsAtom = atom({ plugin: 'conversation-toolbar', key: 'externalButtons' } as const, NO_EXTERNAL_BUTTONS)

type MoveOutcome = { isMoved: true } | { isMoved: false; reason: string; isDeclined: boolean }

function describeError(error: unknown): string {
  return error instanceof Error ? error.message : String(error)
}

function moveAfterTurnMessage(folder: string): string {
  return `After this conversation turn is complete, move the working directory to ${folder}.`
}
async function resolveConfigDirectory($: EngineInterface): Promise<string> {
  const configured = await $.env.get('CLAUDE_CONFIG_DIR')
  if (configured) {
    return configured
  }
  const userProfile = await $.env.get('USERPROFILE')
  const home = userProfile ?? (await $.env.get('HOME')) ?? ''

  return joinWindowsPath(home, '.claude')
}

async function resolveTranscriptPath($: EngineInterface): Promise<string> {
  const sessionId = await $.session.id()
  const projectsDirectory = joinWindowsPath(await resolveConfigDirectory($), 'projects')
  const fileName = `${sessionId}.jsonl`

  const expected = joinWindowsPath(
    projectsDirectory,
    projectDirectoryName(await $.session.cwd()),
    fileName,
  )
  if (await $.fs.exists(expected)) {
    return expected
  }

  // The working directory may have changed since the session started; search
  // every project folder for this session's transcript.
  const entries = await $.fs.list(projectsDirectory).catch(() => [])
  for (const entry of entries) {
    if (entry.kind !== 'dir') {
      continue
    }
    const candidate = joinWindowsPath(projectsDirectory, entry.name, fileName)
    if (await $.fs.exists(candidate)) {
      return candidate
    }
  }

  return expected
}

async function copyToClipboard(
  $: EngineInterface,
  text: string,
  surface?: CopySurface,
): Promise<boolean> {
  const copied = await $.ui.copy({ text, surface }).catch(() => ({ isCopied: false }))
  if (copied.isCopied) {
    return true
  }

  // A remote surface such as the desktop app may not take the copy; fall back
  // to the Windows clipboard directly.
  const script =
    '[Console]::InputEncoding = [System.Text.Encoding]::UTF8; ' +
    'Set-Clipboard -Value ([Console]::In.ReadToEnd())'
  const result = await $.process
    .run(['powershell', '-NoProfile', '-NonInteractive', '-Command', script], {
      stdin: text,
      timeoutMs: 15000,
    })
    .catch(() => undefined)

  return result?.exitCode === 0
}

// Module variables start over on a hot reload; a feedback left showing then
// clears at the next press.
let copyFeedbackTimer: ReturnType<EngineInterface['clock']['after']> | null = null

// The button itself says how the copy went, so a press always shows something
// where the user is looking; the toast carries the path.
async function showCopyFeedback($: EngineInterface, feedback: CopyFeedback): Promise<void> {
  copyFeedbackTimer?.cancel()
  await update($, copyFeedbackAtom, () => feedback)
  copyFeedbackTimer = $.clock.after(COPY_FEEDBACK_DURATION_MS, () => {
    copyFeedbackTimer = null
    void update($, copyFeedbackAtom, () => null)
  })
}

async function copyTranscriptPath($: EngineInterface, surface?: CopySurface): Promise<string> {
  const path = await resolveTranscriptPath($)
  const isCopied = await copyToClipboard($, path, surface)
  const message = isCopied
    ? `Copied transcript path: ${path}`
    : `Could not copy; the transcript path is ${path}`
  await showCopyFeedback($, isCopied ? 'copied' : 'failed').catch(() => undefined)
  $.ui.toast(message)

  return message
}

async function resolveAppDataDirectory($: EngineInterface): Promise<string | undefined> {
  return (await $.env.get('APPDATA')) || undefined
}

async function resolveScratchRoot($: EngineInterface): Promise<string | undefined> {
  const appData = await resolveAppDataDirectory($)

  return appData === undefined ? undefined : joinWindowsPath(appData, 'Claude', 'scratch-workspaces')
}

async function resolveTemporaryRoots($: EngineInterface): Promise<string[]> {
  // $.env.get takes a literal name, so the module's variables can be listed.
  const values = [
    await $.env.get('TEMP').catch(() => undefined),
    await $.env.get('TMP').catch(() => undefined),
    await $.env.get('CLAUDE_CODE_TMPDIR').catch(() => undefined),
  ]

  return values.filter((value): value is string => typeof value === 'string' && value !== '')
}

// What a person can pick: the stored list less scratch, worktree and temporary
// folders (older versions recorded some of those).
async function pickableFolderFilter($: EngineInterface): Promise<(folder: string) => boolean> {
  const scratchRoot = await resolveScratchRoot($)
  const temporaryRoots = await resolveTemporaryRoots($)

  return folder => isPickableFolder(folder, scratchRoot, temporaryRoots)
}

async function readStoredFolders($: EngineInterface): Promise<RecentFolderList> {
  const isPickable = await pickableFolderFilter($)

  return readFolderList(await $.store.get(STORE_KEY_RECENT_FOLDERS)).filter(isPickable)
}

// Other sessions write the same store, so every change starts from what it
// holds now rather than from this session's copy.
async function saveRecentFolders(
  $: EngineInterface,
  change: (stored: RecentFolderList) => RecentFolderList,
): Promise<void> {
  const folders = change(await readStoredFolders($))
  await $.store.set(STORE_KEY_RECENT_FOLDERS, folders)
  await $.state.set(recentFoldersState, folders)
}

async function recordFolder($: EngineInterface, folder: string): Promise<void> {
  if (!(await pickableFolderFilter($))(folder)) {
    return
  }
  await saveRecentFolders($, stored => placeFolderFirst(stored, folder))
}

type SessionRecordFile = { path: string; mtimeMs: number }

// <APPDATA>\Claude\claude-code-sessions\<account>\<organization>\local_<id>.json
async function listSessionRecordFiles(
  $: EngineInterface,
  sessionsRoot: string,
): Promise<SessionRecordFile[]> {
  const files: SessionRecordFile[] = []
  for (const account of await $.fs.list(sessionsRoot).catch(() => [])) {
    if (account.kind !== 'dir') {
      continue
    }
    const accountPath = joinWindowsPath(sessionsRoot, account.name)
    for (const organization of await $.fs.list(accountPath).catch(() => [])) {
      if (organization.kind !== 'dir') {
        continue
      }
      const organizationPath = joinWindowsPath(accountPath, organization.name)
      for (const entry of await $.fs.list(organizationPath).catch(() => [])) {
        if (entry.kind === 'file' && /^local_.+\.json$/.test(entry.name)) {
          files.push({ path: joinWindowsPath(organizationPath, entry.name), mtimeMs: entry.mtimeMs })
        }
      }
    }
  }

  return files
}

// The first time the toolbar loads, the folders of the desktop app's own
// session records fill the list behind the ones already recorded.
async function seedFromDesktopSessions($: EngineInterface): Promise<void> {
  if ((await $.store.get(STORE_KEY_IS_SEEDED)) === true) {
    return
  }
  const appData = await resolveAppDataDirectory($)
  if (appData === undefined) {
    return
  }
  const sessionsRoot = joinWindowsPath(appData, 'Claude', 'claude-code-sessions')
  const files = (await listSessionRecordFiles($, sessionsRoot))
    .sort((first, second) => second.mtimeMs - first.mtimeMs)
    .slice(0, SESSION_RECORD_READ_LIMIT)
  const records: SessionRecordFolder[] = []
  for (const file of files) {
    const text = await $.fs.read(file.path).catch(() => undefined)
    const record = typeof text === 'string' ? readSessionRecordFolder(text, file.mtimeMs) : null
    if (record !== null) {
      records.push(record)
    }
  }
  const seeded = rankSessionFolders(records).filter(await pickableFolderFilter($))
  await saveRecentFolders($, stored => mergeFolderLists(stored, seeded))
  await $.store.set(STORE_KEY_IS_SEEDED, true)
}

function describeToolResult(result: McpToolResult): string {
  return result.content
    .map(block => (typeof block.text === 'string' ? block.text : ''))
    .join(' ')
    .trim()
}

// The desktop app's own tool: it asks the person to approve the folder (unless
// permissions are bypassed) and moves the session when the current turn ends.
async function moveSession($: EngineInterface, folder: string): Promise<MoveOutcome> {
  try {
    const result = await $.mcp.call('ccd_directory', 'change_directory', { path: folder })
    if (!result.isError) {
      return { isMoved: true }
    }
    const reason = describeToolResult(result) || 'the desktop app refused the move'

    return { isMoved: false, reason, isDeclined: /declin|denied|reject|cancel/i.test(reason) }
  } catch (error) {
    return { isMoved: false, reason: describeError(error), isDeclined: false }
  }
}

async function hasConversationStarted($: EngineInterface, isWorking: boolean): Promise<boolean> {
  return isWorking || (await $.session.turns()) > 0
}

// Module variables start over on a hot reload; session.start restarts the
// dots of a move still pending.
let movingDotsTimer: ReturnType<EngineInterface['clock']['every']> | null = null

function startMovingDots($: EngineInterface): void {
  if (movingDotsTimer === null) {
    movingDotsTimer = $.clock.every(MOVING_DOTS_INTERVAL_MS, () =>
      void update($, movingDotsAtom, dots => ((dots ?? 1) % MOVING_DOTS_MAXIMUM) + 1),
    )
  }
}

function stopMovingDots(): void {
  movingDotsTimer?.cancel()
  movingDotsTimer = null
}

// The desktop app moves the session when a turn ends, not at once: the toolbar
// shows the target beside the folder list until the session is there.
async function markPendingMove($: EngineInterface, target: string): Promise<void> {
  const root = normalizeFolder(await $.session.root().catch(() => ''))
  if (folderIdentity(root) === folderIdentity(target)) {
    await update($, pendingMoveAtom, () => null)
    stopMovingDots()
    return
  }
  await update($, pendingMoveAtom, () => target)
  startMovingDots($)
}

// Clears the pending move once the session has reached it.
async function settlePendingMove($: EngineInterface): Promise<void> {
  const pending = await read($, pendingMoveAtom)
  if (pending === null) {
    stopMovingDots()
    return
  }
  const root = normalizeFolder(await $.session.root())
  if (folderIdentity(root) === folderIdentity(pending)) {
    await update($, pendingMoveAtom, () => null)
    stopMovingDots()
  } else {
    startMovingDots($)
  }
}

function whenMoveApplies(isWorking: boolean): string {
  return isWorking ? 'when this turn ends' : 'after your next message'
}

// What happened, for a command's output; `isShownInToolbar` when the toolbar
// already shows it (the folder list or the pending-move note), so no toast.
type FolderOpening = { message: string; isShownInToolbar: boolean }

async function openFolder($: EngineInterface, folder: string, isWorking: boolean): Promise<FolderOpening> {
  const target = normalizeFolder(folder)
  await recordFolder($, target).catch(() => undefined)
  const hasStarted = await hasConversationStarted($, isWorking)
  const outcome = await moveSession($, target)
  if (outcome.isMoved) {
    await markPendingMove($, target).catch(() => undefined)
    // A turn a plugin submits does not make the desktop app apply the move;
    // only a message the person sends does.
    const message = hasStarted
      ? `This conversation moves to ${target} ${whenMoveApplies(isWorking)}`
      : `This conversation starts in ${target}`
    return { message, isShownInToolbar: true }
  }
  if (outcome.isDeclined) {
    return { message: `The move to ${target} was declined`, isShownInToolbar: false }
  }
  if (!hasStarted) {
    return { message: `Could not open ${target}: ${outcome.reason}`, isShownInToolbar: false }
  }

  // A running conversation may refuse the move; leave the model a note to
  // make it once this turn is done.
  const appended = await $.session
    .append({
      message: { type: 'user', content: [{ type: 'text', text: moveAfterTurnMessage(target) }] },
    })
    .catch((error: unknown) => ({ deny: describeError(error) }))
  if ('deny' in appended) {
    return { message: `Could not move to ${target}: ${outcome.reason}`, isShownInToolbar: false }
  }
  await markPendingMove($, target).catch(() => undefined)

  return {
    message: `Could not move now (${outcome.reason}); Claude will move to ${target} after this turn`,
    isShownInToolbar: true,
  }
}

// Toasts only what the toolbar does not show: a failed or declined move.
async function openFolderWithToast($: EngineInterface, folder: string, isWorking: boolean): Promise<void> {
  const opening = await openFolder($, folder, isWorking)
  if (!opening.isShownInToolbar) {
    $.ui.toast(opening.message)
  }
}

// `/folder <name or path>`: the toolbar is drawn only once a session exists,
// so a new conversation can pick its folder with this as its first message.
async function runFolderCommand($: EngineInterface, query: string): Promise<string> {
  const wanted = query.trim().replace(/^"(.*)"$/, '$1')
  if (wanted === '') {
    return 'Pick a folder in the toolbar above the prompt, or name one: /folder <name or path>'
  }
  const folder = isAbsoluteFolder(wanted) ? wanted : findFolder(await readStoredFolders($), wanted)
  if (folder === undefined) {
    return `No recent folder matches "${wanted}"`
  }
  if (!(await $.fs.exists(folder).catch(() => false))) {
    return `${folder} does not exist`
  }

  return (await openFolder($, folder, false)).message
}

async function pickFolder($: EngineInterface, initialFolder: string | undefined): Promise<string | null> {
  const script = joinWindowsPath($.plugin.root, 'scripts', 'Pick_Folder.ps1')
  const argv = [
    'powershell',
    '-NoProfile',
    '-NonInteractive',
    '-ExecutionPolicy',
    'Bypass',
    '-STA',
    '-File',
    script,
    '-Title',
    'Choose a folder for this conversation',
  ]
  if (initialFolder !== undefined) {
    argv.push('-InitialFolder', initialFolder)
  }
  const result = await $.process.run(argv, { timeoutMs: FOLDER_PICKER_TIMEOUT_MS })
  if (result.exitCode !== 0) {
    throw new Error(result.stderr.trim() || `the folder picker exited with code ${result.exitCode}`)
  }
  const folder = result.stdout.trim()

  return folder === '' ? null : folder
}

async function browseAndOpen($: EngineInterface, isWorking: boolean): Promise<void> {
  try {
    const lastUsedFolder = (await readStoredFolders($))[0]
    const folder = await pickFolder($, lastUsedFolder)
    if (folder !== null) {
      await openFolderWithToast($, folder, isWorking)
    }
  } catch (error) {
    $.ui.toast(`Could not show the folder picker: ${describeError(error)}`)
  }
}

// Module variables start over on a hot reload; this one only saves a redundant
// store write.
let lastRecordedFolder = ''

async function recordCurrentFolder($: EngineInterface): Promise<void> {
  const root = normalizeFolder(await $.session.root())
  if (folderIdentity(root) === lastRecordedFolder) {
    return
  }
  lastRecordedFolder = folderIdentity(root)
  await recordFolder($, root)
}

function usageSnapshot(usage: {
  context: { tokens?: number; window: number; percent?: number }
  rateLimits: readonly { kind: string; percentUsed: number; resetsAt?: string }[]
}): UsageSnapshot {
  return {
    context: { tokens: usage.context.tokens, window: usage.context.window, percent: usage.context.percent },
    rateLimits: usage.rateLimits.map(window => ({ kind: window.kind, percentUsed: window.percentUsed, resetsAt: window.resetsAt })),
  }
}

type UsageEndpointCache = { fetchedAtMs: number; windows: UsageWindow[] }

function readUsageEndpointCache(value: unknown): UsageEndpointCache | null {
  if (typeof value !== 'object' || value === null) {
    return null
  }
  const cache = value as { fetchedAtMs?: unknown; windows?: unknown }
  if (typeof cache.fetchedAtMs !== 'number' || !Array.isArray(cache.windows) || cache.fetchedAtMs < processStartedAtMs) {
    return null
  }
  const windows = cache.windows.filter(
    (window): window is UsageWindow =>
      typeof window === 'object' && window !== null && typeof window.kind === 'string' && typeof window.percentUsed === 'number',
  )

  return { fetchedAtMs: cache.fetchedAtMs, windows }
}

// Module variables start over on a hot reload, as the timers do.
// The shared cache does not say whose account it read, and switching accounts
// starts the sessions over, so an answer from before this process may be
// another account's: it is neither shown nor taken as fresh.
const processStartedAtMs = Date.now()
let latestSessionUsage: UsageSnapshot | null = null
let usageEndpointRequest: Promise<void> | null = null
// The session's window readings come from response headers, so they are fresh
// only during a turn and as it ends; 0 before any turn of this process.
let isTurnRunning = false
let lastTurnCompletedAtMs = 0

function sessionWindowsReadAtMs(): number {
  return isTurnRunning ? Date.now() : lastTurnCompletedAtMs
}

// The plan's usage windows, the Fable weekly quota among them, from the same
// endpoint the engine's /usage reads. Every session shares one cached answer,
// so the endpoint is asked at most once a minute however many sessions run.
async function refreshUsageEndpoint($: EngineInterface, maximumAgeMs: number): Promise<void> {
  const cached = readUsageEndpointCache(await $.store.get(STORE_KEY_USAGE_ENDPOINT))
  if (cached !== null && Date.now() - cached.fetchedAtMs < maximumAgeMs) {
    return
  }
  if (usageEndpointRequest !== null) {
    return usageEndpointRequest
  }
  usageEndpointRequest = (async () => {
    try {
      const authorization = await $.session.authorize()
      if (authorization === null) {
        return
      }
      // The endpoint Claude Code's /usage reads, with the session's own authorization.
      const response = await $.http.fetch('https://api.anthropic.com/api/oauth/usage', {
        auth: authorization.handle,
        headers: { 'Content-Type': 'application/json', 'anthropic-beta': 'oauth-2025-04-20' },
      })
      if (!response.ok) {
        $.ui.log(`The usage endpoint answered ${response.status}`, { to: 'debug' })
        return
      }
      const windows = parseUsageEndpoint(JSON.parse(response.text))
      await $.store.set(STORE_KEY_USAGE_ENDPOINT, { fetchedAtMs: Date.now(), windows })
    } catch (error: unknown) {
      $.ui.log(`Reading the usage endpoint failed: ${describeError(error)}`, { to: 'debug' })
    } finally {
      usageEndpointRequest = null
    }
  })()

  return usageEndpointRequest
}

// The snapshot the widgets draw: the session's context, and the header and
// endpoint windows, the fresher first. Not written to state from a render.
async function composeUsage($: EngineInterface): Promise<UsageSnapshot | null> {
  if (latestSessionUsage === null) {
    latestSessionUsage = usageSnapshot(await $.session.usage())
  }
  const cached = readUsageEndpointCache(await $.store.get(STORE_KEY_USAGE_ENDPOINT))

  return {
    context: latestSessionUsage.context,
    rateLimits: mergeWindows(latestSessionUsage.rateLimits, cached?.windows ?? [], sessionWindowsReadAtMs(), cached?.fetchedAtMs ?? 0),
  }
}

// Writes the snapshot only when a figure changed, so a quiet session does not redraw.
async function publishUsage($: EngineInterface): Promise<void> {
  try {
    const snapshot = await composeUsage($)
    const current = await read($, usageAtom)
    if (JSON.stringify(current) !== JSON.stringify(snapshot)) {
      await update($, usageAtom, () => snapshot)
    }
  } catch (error: unknown) {
    $.ui.log(`Updating the usage widgets failed: ${describeError(error)}`, { to: 'debug' })
  }
}

async function refreshSessionUsage($: EngineInterface): Promise<void> {
  try {
    latestSessionUsage = usageSnapshot(await $.session.usage())
  } catch (error: unknown) {
    $.ui.log(`Reading the session usage failed: ${describeError(error)}`, { to: 'debug' })
    return
  }
  await publishUsage($)
}

// Takes the engine's agent list into the dots' records, writing only when a
// state changed so a quiet session does not redraw.
async function refreshSubagents($: EngineInterface): Promise<void> {
  try {
    const listed = await $.agent.list()
    const nowMs = Date.now()
    const current = (await read($, subagentsAtom)) ?? []
    if (JSON.stringify(mergeListedAgents(current, listed, nowMs)) !== JSON.stringify(current)) {
      await writeSubagents($, records => mergeListedAgents(records, listed, nowMs))
    }
  } catch (error: unknown) {
    $.ui.log(`Reading the subagent list failed: ${describeError(error)}`, { to: 'debug' })
  }
}

// Writes the dots' records and asks for a redraw: the desktop app does not
// redraw the band on the state change alone, so a dot would wait for the
// next unrelated redraw (a usage figure, a turn boundary).
async function writeSubagents(
  $: EngineInterface,
  change: (records: SubagentRecord[]) => SubagentRecord[],
): Promise<void> {
  await update($, subagentsAtom, records => change(records ?? []))
  $.ui.invalidate('ui.render')
}

// Module variables start over on a hot reload, which does not run
// session.start again; every turn boundary makes sure the list is polled.
let subagentListTimer: ReturnType<EngineInterface['clock']['every']> | null = null

function ensureSubagentPolling($: EngineInterface): void {
  if (subagentListTimer === null) {
    subagentListTimer = $.clock.every(SUBAGENT_LIST_INTERVAL_MS, () => {
      void refreshSubagents($)
      void checkMonitorDeadlines($)
    })
    void refreshSubagents($)
  }
  ensureMonitorBackfill($)
}

// Writes the clocks' records and asks for a redraw, as writeSubagents does.
async function writeMonitors(
  $: EngineInterface,
  change: (records: MonitorRecord[]) => MonitorRecord[],
): Promise<void> {
  await update($, monitorsAtom, records => change(records ?? []))
  $.ui.invalidate('ui.render')
}

// Module variables start over on a hot reload, and a Monitor started before
// this module loaded raised no tool.call here: once per load, the transcript
// gives the Monitors back.
let monitorBackfill: Promise<void> | null = null

function ensureMonitorBackfill($: EngineInterface): void {
  if (monitorBackfill !== null) {
    return
  }
  monitorBackfill = (async () => {
    try {
      const transcript = await $.fs.read(await resolveTranscriptPath($))
      const nowMs = Date.now()
      const parsed = expireMonitors(parseTranscriptMonitors(typeof transcript === 'string' ? transcript : '', nowMs), nowMs)
      const current = (await read($, monitorsAtom)) ?? []
      const merged = mergeMonitorRecords(current, parsed)
      if (JSON.stringify(merged) !== JSON.stringify(current)) {
        await writeMonitors($, () => merged)
      }
    } catch (error: unknown) {
      $.ui.log(`Reading the Monitors from the transcript failed: ${describeError(error)}`, { to: 'debug' })
    }
  })()
}

let lastMonitorRedrawMs = 0

// Ends the clocks past their deadline, and redraws a waiting clock now and
// then so its countdown and tooltip move on.
async function checkMonitorDeadlines($: EngineInterface): Promise<void> {
  try {
    const nowMs = Date.now()
    const current = (await read($, monitorsAtom)) ?? []
    const expired = expireMonitors(current, nowMs)
    if (JSON.stringify(expired) !== JSON.stringify(current)) {
      lastMonitorRedrawMs = nowMs
      await writeMonitors($, records => expireMonitors(records, nowMs))
    } else if (
      activeMonitors(current).length > 0 &&
      (isCountingSeconds(activeMonitors(current), nowMs) || nowMs - lastMonitorRedrawMs >= MONITOR_COUNTDOWN_REFRESH_MS)
    ) {
      lastMonitorRedrawMs = nowMs
      $.ui.invalidate('ui.render')
    }
  } catch (error: unknown) {
    $.ui.log(`Checking the Monitor deadlines failed: ${describeError(error)}`, { to: 'debug' })
  }
}

function monitorTooltip(active: readonly MonitorRecord[], nowMs: number): string {
  return [monitorSummary(active), ...monitorLines(active, nowMs)].join('\n')
}

async function resolveButtonFolder($: EngineInterface): Promise<string | undefined> {
  const temporary = (await $.env.get('TEMP').catch(() => undefined)) || (await $.env.get('TMP').catch(() => undefined))

  return temporary ? joinWindowsPath(temporary, BUTTON_FOLDER_NAME, BUTTON_SUBFOLDER_NAME) : undefined
}

// Module variables start over on a hot reload; every turn boundary and draw
// makes sure the button folder is polled.
let externalButtonTimer: ReturnType<EngineInterface['clock']['every']> | null = null
let isReadingExternalButtons = false

function ensureExternalButtonPolling($: EngineInterface): void {
  if (externalButtonTimer === null) {
    externalButtonTimer = $.clock.every(EXTERNAL_BUTTON_POLL_MS, () => void refreshExternalButtons($))
    void refreshExternalButtons($)
  }
}

// Reads the button folder (only the files there, usually none) and writes the
// buttons when they changed, or every poll while one animates: each poll moves
// the dots one frame on, so a late timer never skips a frame.
async function refreshExternalButtons($: EngineInterface): Promise<void> {
  if (isReadingExternalButtons) {
    return
  }
  isReadingExternalButtons = true
  try {
    const folder = await resolveButtonFolder($)
    const entries = folder === undefined ? [] : await $.fs.list(folder).catch(() => [])
    const pressFileNames = new Set(
      entries.filter(entry => entry.kind === 'file' && entry.name.endsWith(PRESS_FILE_SUFFIX)).map(entry => entry.name),
    )
    const files: ButtonFile[] = []
    for (const entry of entries) {
      if (folder === undefined || entry.kind !== 'file' || !entry.name.endsWith(BUTTON_FILE_SUFFIX)) {
        continue
      }
      // The program may delete the file between the list and the read.
      const text = await $.fs.read(joinWindowsPath(folder, entry.name)).catch(() => undefined)
      if (typeof text === 'string') {
        files.push({ name: entry.name, mtimeMs: entry.mtimeMs, text })
      }
    }
    const records = files.length === 0 ? [] : buttonRecords(files, pressFileNames, await $.session.id(), Date.now())
    const current = (await read($, externalButtonsAtom)) ?? NO_EXTERNAL_BUTTONS
    const isUnchanged = JSON.stringify(current.buttons) === JSON.stringify(records)
    if (isUnchanged && !isAnimating(records)) {
      return
    }
    // Buttons that just appeared start at the first frame (three dots).
    const frame = current.buttons.length === 0 || !isAnimating(records) ? 0 : current.frame + 1
    await update($, externalButtonsAtom, () => ({ buttons: records, frame }))
    $.ui.invalidate('ui.render')
  } catch (error: unknown) {
    $.ui.log(`Reading the toolbar button folder failed: ${describeError(error)}`, { to: 'debug' })
  } finally {
    isReadingExternalButtons = false
  }
}

// A press writes the button's press file for its program, and the button
// shows its pressed label until the program removes it.
async function pressExternalButton($: EngineInterface, record: ExternalButtonRecord): Promise<void> {
  if (record.isPressed) {
    return
  }
  const folder = await resolveButtonFolder($)
  if (folder === undefined) {
    $.ui.toast(`Could not press ${record.label}: TEMP is not set`)
    return
  }
  try {
    const button = ExternalButton.fromRecord(record)
    await $.fs.write(joinWindowsPath(folder, button.pressFileName), pressNote(await $.session.id(), Date.now()))
    await update($, externalButtonsAtom, state => {
      const current = state ?? NO_EXTERNAL_BUTTONS
      return {
        ...current,
        buttons: current.buttons.map(shown => (shown.id === record.id ? { ...shown, isPressed: true } : shown)),
      }
    })
    $.ui.invalidate('ui.render')
  } catch (error: unknown) {
    $.ui.toast(`Could not press ${record.label}: ${describeError(error)}`)
  }
}

// The desktop app's own pane of background tasks, opened through the app's
// session MCP server; a surface without it (the terminal) gets a toast.
async function openBackgroundTasksPane($: EngineInterface): Promise<void> {
  try {
    const result = await $.mcp.call(TASKS_PANE_SERVER, TASKS_PANE_TOOL, { pane: 'tasks' })
    if (result.isError) {
      const text = result.content.find(block => block.type === 'text')?.text ?? 'the app refused'
      $.ui.toast(`Could not open the background tasks pane: ${text}`)
    }
  } catch (error: unknown) {
    $.ui.toast(`Could not open the background tasks pane: ${describeError(error)}`)
  }
}

function subagentTooltip(records: readonly SubagentRecord[]): string {
  const lines = subagentLines(records)
  const shown = lines.slice(0, SUBAGENT_TOOLTIP_LINE_LIMIT)
  const more = lines.length > shown.length ? [`… ${lines.length - shown.length} more`] : []
  return [subagentSummary(records), ...shown, ...more].join('\n')
}

// The usage widgets, left to right: the model's weekly ring (Fable), the
// context bar and its token count (a button that pins the detail row open),
// the 5-hour ring and the weekly ring, each ring drawn alike. Hovering a
// widget shows its SVG title as a tooltip; an Svg takes no press, so the count
// is the click target. The terminal gets one dim line and the detail row on demand.
function usageElements(
  $: EngineInterface,
  e: Parameters<Parameters<EngineInterface['ui']['resolve']>[0] extends infer Argument ? (argument: Argument) => void : never>[0],
  widgets: ReturnType<typeof usageWidgets>,
  isPinned: boolean,
) {
  const togglePin = () => void update($, usageDetailsPinnedAtom, value => !value)
  if (e.surface === 'terminal') {
    const { Box, Button, Text } = $.ui.resolve(e)

    return {
      row: (
        <Box key="usage-widgets" flexDirection="row" columnGap={1}>
          <Text dimColor>{usageText(widgets)}</Text>
          <Button key="usage-details" label={isPinned ? 'Hide' : 'Details'} plain dimColor onPress={togglePin} />
        </Box>
      ),
      details: isPinned ? (
        <Box key="usage-detail-row" flexDirection="column">
          {widgets.details.map(line => (
            <Text dimColor>{line}</Text>
          ))}
        </Box>
      ) : null,
    }
  }
  const { Box, Button, Svg } = $.ui.resolve(e)
  // Tooltips take the single-spaced sentences; only the pinned block is aligned.
  const { fiveHour: fiveHourLine, weekly: weeklyLine, model: modelLine, context: contextLine } = widgets.tooltips
  const detailSize = detailBlockSize(widgets.details)

  return {
    row: (
      <Box key="usage-widgets" flexDirection="row" columnGap={1} alignItems="center">
        <Box key="model-weekly-ring">
          <Svg
            source={quotaRingSvg(widgets.modelWeekly.window?.percentUsed ?? null, modelLine)}
            alt={modelLine}
            width={RING_SIZE_PX}
            height={RING_SIZE_PX}
            isInteractive
          />
        </Box>
        <Button key="usage-details" label={widgets.context.label} plain dimColor={!isPinned} onPress={togglePin} />
        <Box key="context-bar">
          <Svg
            source={contextBarSvg(widgets.context.percentOfScale, widgets.context.color, contextLine)}
            alt={contextLine}
            width={BAR_WIDTH_PX}
            height={BAR_HEIGHT_PX}
            isInteractive
          />
        </Box>
        <Box key="five-hour-ring">
          <Svg
            source={quotaRingSvg(widgets.fiveHour?.percentUsed ?? null, fiveHourLine)}
            alt={fiveHourLine}
            width={RING_SIZE_PX}
            height={RING_SIZE_PX}
            isInteractive
          />
        </Box>
        <Box key="seven-day-ring">
          <Svg
            source={quotaRingSvg(widgets.weekly?.percentUsed ?? null, weeklyLine)}
            alt={weeklyLine}
            width={RING_SIZE_PX}
            height={RING_SIZE_PX}
            isInteractive
          />
        </Box>
      </Box>
    ),
    // Drawn only while pinned: the desktop app does not hide a Box drawn
    // display "none", so a hover reveal would show the row all the time.
    // The block is Consolas text in an SVG, right-aligned under the widgets.
    details: isPinned ? (
      <Box key="usage-detail-row" flexDirection="row" justifyContent="flex-end">
        <Svg source={detailBlockSvg(widgets.details)} alt={widgets.details.join('; ')} width={detailSize.width} height={detailSize.height} />
      </Box>
    ) : null,
  }
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'copy-transcript-path',
      description: 'Copy the path of this conversation transcript (.jsonl)',
    })
    await $.command.register({
      name: 'folder',
      description: 'Open or move this conversation to a recent folder (matched by name) or a path',
      argumentHint: '<name or path>',
    })
    await $.state.set(recentFoldersState, await readStoredFolders($))
    lastRecordedFolder = folderIdentity(e.cwd)
    await recordFolder($, e.cwd).catch(() => undefined)
    void seedFromDesktopSessions($).catch((error: unknown) =>
      $.ui.log(`Reading the desktop session records failed: ${describeError(error)}`, { to: 'debug' }),
    )
    // Live usage: the session's own figures (a free local read) every few
    // seconds, so the context bar follows each response within a turn; the
    // plan windows from the shared endpoint cache once a minute.
    void refreshUsageEndpoint($, USAGE_ENDPOINT_INTERVAL_MS - 5_000).then(() => refreshSessionUsage($))
    // A move still pending from before a reload gets its dots back; the same
    // cheap check every few seconds clears the note once the session is there.
    void settlePendingMove($).catch(() => undefined)
    $.clock.every(SESSION_USAGE_INTERVAL_MS, () => {
      void refreshSessionUsage($)
      void settlePendingMove($).catch(() => undefined)
    })
    $.clock.every(USAGE_ENDPOINT_INTERVAL_MS, () =>
      void refreshUsageEndpoint($, USAGE_ENDPOINT_INTERVAL_MS - 5_000).then(() => publishUsage($)),
    )
    // The subagent dots follow the engine's agent list (a local read).
    ensureSubagentPolling($)
    ensureExternalButtonPolling($)

    return next(e)
  })

  // A started subagent gets its dot at once, before the next list read.
  on('agent.spawn', async ($, e, next) => {
    ensureSubagentPolling($)
    const result = await next(e)
    const agentId = result.agentId
    if (agentId !== undefined) {
      const agent = { id: agentId, description: e.description, type: e.subagentType }
      await writeSubagents($, records => recordSpawn(records, agent, Date.now())).catch(() => undefined)
    }

    return result
  })

  // A Monitor of the main conversation gets its waiting clock once the tool
  // answers with its task id.
  on('tool.call', { tool: 'Monitor' }, async ($, e, next) => {
    ensureSubagentPolling($)
    const ran = await next(e)
    if (e.agentId === undefined && ran.deny === undefined && ran.isError !== true) {
      const monitor = readMonitorStart(ran.result, e.description, Date.now())
      if (monitor !== null) {
        await writeMonitors($, records => recordMonitorStart(records, monitor)).catch(() => undefined)
      }
    }

    return ran
  })

  on('tool.call', { tool: 'TaskStop' }, async ($, e, next) => {
    const ran = await next(e)
    const taskId = e.task_id ?? e.shell_id
    if (e.agentId === undefined && taskId !== undefined && ran.deny === undefined && ran.isError !== true) {
      await writeMonitors($, records => recordMonitorEnd(records, taskId, 'stopped', Date.now())).catch(() => undefined)
    }

    return ran
  })

  // A Monitor's last notification carries a status (completed, failed,
  // killed...); its event notifications carry none.
  on('prompt.submit', async ($, e, next) => {
    if (e.origin.kind === 'task-notification') {
      const endings = parseNotificationEndings(e.text)
      if (endings.length > 0) {
        await writeMonitors($, records => applyEndings(records, endings, Date.now())).catch(() => undefined)
      }
    }

    return next(e)
  })

  // A session moved by the desktop app, the model or this toolbar records its
  // new folder at the next turn boundary.
  on('turn.start', async ($, e, next) => {
    isTurnRunning = true
    ensureSubagentPolling($)
    ensureExternalButtonPolling($)
    await recordCurrentFolder($).catch(() => undefined)
    await settlePendingMove($).catch(() => undefined)

    return next(e)
  })

  on('turn.complete', async ($, e, next) => {
    // A subagent's run ends in a turn.complete of its own: its dot takes the
    // outcome; the main loop's turn state is untouched.
    const agentId = e.agentId
    if (agentId !== undefined) {
      const result = await next(e)
      await writeSubagents($, records => recordTurnEnd(records, agentId, e.reason, Date.now())).catch(() => undefined)

      return result
    }
    isTurnRunning = false
    lastTurnCompletedAtMs = Date.now()
    const result = await next(e)
    await recordCurrentFolder($).catch(() => undefined)
    await settlePendingMove($).catch(() => undefined)
    // A turn spends quota: ask the endpoint again unless another session just did.
    void refreshUsageEndpoint($, 15_000).then(() => refreshSessionUsage($))

    return result
  })

  // The engine measures the context fill and the rate-limit windows after each
  // turn and whenever a plan window moves a point; a moved window also asks
  // the endpoint again so the Fable ring follows.
  on('session.measure', async ($, e, next) => {
    latestSessionUsage = usageSnapshot({ context: e.context, rateLimits: e.rateLimits })
    await publishUsage($)
    if (e.changed.includes('rateLimits')) {
      void refreshUsageEndpoint($, 15_000).then(() => publishUsage($))
    }

    return next(e)
  })

  on('command.run', { command: 'copy-transcript-path' }, async $ => {
    return { text: await copyTranscriptPath($) }
  })

  on('command.run', { command: 'folder' }, async ($, e) => {
    return { text: await runFolderCommand($, e.args) }
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (e.props.hasSurvey || e.props.view.agentId !== undefined) {
      return next(e)
    }

    const elements = $.ui.resolve(e)
    const { Box, Button, Text } = elements
    const copyFeedback = (await read($, copyFeedbackAtom)) ?? 'idle'
    const copyButton = (
      <Button
        key="copy-transcript-path"
        label={COPY_BUTTON_LABELS[copyFeedback]}
        variant="secondary"
        onPress={press => void copyTranscriptPath($, press.surface)}
      />
    )
    // The usage widgets at the right end. Before the first publication the
    // figures are composed here (a render reads state, it never writes it).
    const usage = (await read($, usageAtom)) ?? (await composeUsage($).catch(() => null))
    const modelId = await $.session.model().catch(() => '')
    const usageParts = usageElements($, e, usageWidgets(usage, Date.now(), modelId), await read($, usageDetailsPinnedAtom))
    // One dot per subagent of this session, drawn once there is one; hovering
    // lists them. The terminal shows the counts as text.
    const subagents = (await read($, subagentsAtom)) ?? []
    // A clock per Monitor still watching, left of the dots. A hot reload at an
    // idle moment raises no turn: the first draw starts the poll and the
    // transcript read (their writes come after this draw).
    ensureSubagentPolling($)
    ensureExternalButtonPolling($)
    const monitors = activeMonitors((await read($, monitorsAtom)) ?? [])
    // Buttons other programs asked for, after the dots; a press writes the
    // button's press file for its program.
    const externalButtons = (await read($, externalButtonsAtom)) ?? NO_EXTERNAL_BUTTONS
    const externalButtonRow =
      externalButtons.buttons.length > 0 ? (
        <Box key="external-buttons" flexDirection="row" columnGap={1}>
          {externalButtons.buttons.map(record => (
            <Button
              key={`external-button-${record.id}`}
              label={ExternalButton.fromRecord(record).text(externalButtons.frame, record.isPressed)}
              variant="secondary"
              dimColor={record.isPressed}
              onPress={() => void pressExternalButton($, record)}
            />
          ))}
        </Box>
      ) : null
    let subagentIndicator = null
    if (subagents.length > 0 || monitors.length > 0) {
      // An Svg takes no press and a Button holds no Svg, so a one-glyph plain
      // button beside the dots opens the desktop app's background tasks pane.
      const openTasks = (
        <Button
          key="open-background-tasks"
          label={OPEN_TASKS_GLYPH}
          plain
          dimColor
          onPress={() => void openBackgroundTasksPane($)}
        />
      )
      const nowMs = Date.now()
      if (e.surface !== 'terminal' && 'Svg' in elements) {
        const { Svg } = elements
        subagentIndicator = (
          <Box key="subagent-dots" flexDirection="row" alignItems="center">
            {monitors.length > 0 ? (
              <Box key="monitor-clocks">
                <Svg
                  source={monitorClocksSvg(monitors, monitorTooltip(monitors, nowMs), nowMs)}
                  alt={monitorSummary(monitors)}
                  width={monitorClocksWidth(monitors, nowMs)}
                  height={DOTS_HEIGHT_PX}
                  isInteractive
                />
              </Box>
            ) : null}
            {subagents.length > 0 ? (
              <Box key="subagent-dot-row">
                <Svg
                  source={subagentDotsSvg(subagents, subagentTooltip(subagents))}
                  alt={subagentSummary(subagents)}
                  width={subagentDotsWidth(subagents)}
                  height={DOTS_HEIGHT_PX}
                  isInteractive
                />
              </Box>
            ) : null}
            {openTasks}
          </Box>
        )
      } else {
        subagentIndicator = (
          <Box key="subagent-dots" flexDirection="row" columnGap={1}>
            {monitors.length > 0 ? <Text dimColor>{monitorText(monitors)}</Text> : null}
            {subagents.length > 0 ? <Text dimColor>{subagentText(subagents)}</Text> : null}
            {openTasks}
          </Box>
        )
      }
    }
    if (!('Select' in elements)) {
      return (
        <Box flexDirection="column">
          <Box flexDirection="row" columnGap={1}>
            {subagentIndicator}
            {externalButtonRow}
            {copyButton}
            {usageParts.row}
          </Box>
          {usageParts.details}
        </Box>
      )
    }
    const { Select } = elements

    const recentFolders = await $.state.get(recentFoldersState)
    // Before session.start has filled the state (or in a test), read the store.
    const isPickable = await pickableFolderFilter($)
    const stored = (recentFolders.version === 0 ? await readStoredFolders($) : (recentFolders.value ?? [])).filter(isPickable)
    // The current folder always shows, even one the list does not keep (a
    // worktree); a scratch workspace shows as "No folder".
    const root = normalizeFolder(await $.session.root())
    const scratchRoot = await resolveScratchRoot($)
    const isScratch = scratchRoot !== undefined && isFolderInside(root, scratchRoot)
    const isListed = stored.some(folder => folderIdentity(folder) === folderIdentity(root))
    const folders = isScratch || isListed ? stored : [root, ...stored]
    const currentFolder = isScratch
      ? undefined
      : folders.find(folder => folderIdentity(folder) === folderIdentity(root))
    const labelWidth = Math.min(
      MAXIMUM_FOLDER_LABEL_WIDTH,
      Math.max(MINIMUM_FOLDER_LABEL_WIDTH, e.props.bodyColumns - COLUMNS_BESIDE_FOLDER_LABEL),
    )
    // The folders, then "Browse…" last, which opens the folder picker.
    const options = [
      ...[
        ...(currentFolder === undefined ? [{ value: NO_FOLDER_CHOSEN, label: 'No folder' }] : []),
        ...folders.map(folder => ({ value: folder, label: folderOptionLabel(folder, labelWidth) })),
      ].slice(0, SELECT_OPTION_LIMIT - 1),
      { value: BROWSE_OPTION, label: 'Browse…' },
    ]
    const isWorking = e.props.isWorking
    // A move the desktop app has not made yet: "→ Python_Lib  Moving after
    // your next message..." in grey beside the list, the dots cycling. The
    // dots are padded with no-break spaces so the row does not shift.
    const pendingMove = await read($, pendingMoveAtom)
    const isMovePending = pendingMove !== null && folderIdentity(pendingMove) !== folderIdentity(root)
    const movingDots = '.'.repeat(await read($, movingDotsAtom)).padEnd(MOVING_DOTS_MAXIMUM, ' ')
    const pendingMoveNote = isMovePending ? (
      <Box key="pending-move" flexDirection="row" columnGap={1} alignItems="center">
        <Text dimColor>→</Text>
        <Text dimColor bold>{folderOptionLabel(pendingMove, labelWidth)}</Text>
        <Text dimColor>{`Moving ${whenMoveApplies(isWorking)}${movingDots}`}</Text>
      </Box>
    ) : null

    return (
      <Box flexDirection="column" width="100%">
      <Box flexDirection="row" justifyContent="space-between" columnGap={1} width="100%">
        <Box flexDirection="row" columnGap={1} alignItems="center">
          <Select
            key="recent-folders"
            options={options}
            value={currentFolder ?? NO_FOLDER_CHOSEN}
            onSelect={value => {
              if (value === BROWSE_OPTION) {
                // Redraw afterwards so the list shows the current folder again.
                void browseAndOpen($, isWorking).finally(() => $.ui.invalidate('ui.render'))
              } else if (value !== NO_FOLDER_CHOSEN) {
                void openFolderWithToast($, value, isWorking)
              }
            }}
          />
          {pendingMoveNote}
          {subagentIndicator}
          {externalButtonRow}
        </Box>
        <Box flexDirection="row" columnGap={2} alignItems="center">
          {copyButton}
          {usageParts.row}
        </Box>
      </Box>
      {usageParts.details}
      </Box>
    )
  })
}

